package android.graphics.drawable; import android.graphics.*;
public class ColorDrawable extends Drawable { private int color; public ColorDrawable(){} public ColorDrawable(int c){color=c;} public int getColor(){return color;} public void setColor(int c){color=c;invalidateSelf();} public int indroidColor(){return color;} public void draw(Canvas c){Paint p=new Paint();p.setColor(indroidTint(color));p.setAlpha(p.getAlpha()*getAlpha()/255);c.drawRect(getBounds(),p);} }
